/*
 * 我方发出的邮件是不是自动回复（PRD R-SL-08「带 Auto-Submitted 或自动回复标记的我方邮件不算回复」，AC-P1-03，待办 16）。
 * 纯函数，按入库的头字段判断（channel.message.headers：小写名 + 原值）；读的时候判断、不另存列，口径改了不用重放邮件。
 * 自写：只有几条头字段规则，npm 上没有维护中的通用实现。规则：
 * - Auto-Submitted（RFC 3834）：除了 no 以外的值（auto-replied、auto-generated 等，可带参数）；
 * - 各邮件系统常见的自动回复标记：X-Autoreply、X-Autorespond、X-Autogenerated（有这个头即算），Precedence: auto_reply。
 */

const AUTO_REPLY_HEADERS = new Set(['x-autoreply', 'x-autorespond', 'x-autogenerated']);

export function isAutoReply(headers: readonly { key: string; value: string }[]): boolean {
  return headers.some(({ key, value }) => {
    const name = key.toLowerCase();
    const word = value.split(';')[0]!.trim().toLowerCase();
    if (name === 'auto-submitted') return word !== '' && word !== 'no';
    if (name === 'precedence') return word === 'auto_reply';
    return AUTO_REPLY_HEADERS.has(name);
  });
}
